package com.vms.vendorcontractmanagement.service; import com.vms.vendorcontractmanagement.entity.*; import com.vms.vendorcontractmanagement.repository.*; import lombok.*; import org.springframework.scheduling.annotation.*; import org.springframework.security.core.*; import org.springframework.security.core.context.*; import org.springframework.stereotype.*;
@Service @RequiredArgsConstructor public class AuditService {final AuditLogRepository logs;final UserRepository users; @Async public void log(String action,String entity,Long id,String oldValue,String newValue){AuditLog l=new AuditLog();l.setAction(action);l.setEntityName(entity);l.setEntityId(id);l.setOldValue(oldValue);l.setNewValue(newValue);Authentication a=SecurityContextHolder.getContext().getAuthentication();if(a!=null)users.findByEmail(a.getName()).ifPresent(l::setUser);logs.save(l);} }
